:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a3d;
  --text: #f0f0f5;
  --text-muted: #a0a0b8;
  --accent: #7c6cf0;
  --accent-hover: #9a8cf5;
  --accent-pressed: #5e4ed6;
  --radius: 12px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 640px;
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
  line-height: 1.5;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
}

.swatch {
  display: flex;
  flex-direction: column;
  border-radius: var(--radius);
  overflow: hidden;
  background: #1e1e2f;
  border: 1px solid rgba(255, 255, 255, 0.08);
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.3);
}

.swatch-color {
  height: 120px;
  width: 100%;
  transition: background-color 0.3s ease;
}

.swatch-info {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 6px;
}

.hex-code {
  font-family: 'SF Mono', 'Cascadia Code', 'Consolas', monospace;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--text);
}

.lock-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 6px 10px;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  background: transparent;
  color: var(--text-muted);
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
}

.lock-btn:hover {
  border-color: var(--accent);
  color: var(--text);
  background: rgba(124, 108, 240, 0.1);
}

.lock-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.95);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.lock-icon {
  font-size: 0.9rem;
  line-height: 1;
}

.generate-btn {
  padding: 14px 24px;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: #fff;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: 2px solid var(--accent-hover);
  outline-offset: 3px;
}

.generate-btn:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

@media (max-width: 520px) {
  .palette {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }

  .swatch:last-child {
    grid-column: 1 / -1;
  }

  .swatch-color {
    height: 100px;
  }

  .card {
    padding: 24px 16px;
    gap: 20px;
  }

  h1 {
    font-size: 1.5rem;
  }
}

@media (max-width: 360px) {
  body {
    padding: 12px;
  }

  .card {
    padding: 20px 12px;
  }

  .palette {
    grid-template-columns: 1fr;
  }

  .swatch:last-child {
    grid-column: auto;
  }

  .swatch {
    flex-direction: row;
  }

  .swatch-color {
    height: auto;
    width: 80px;
    flex-shrink: 0;
  }

  .swatch-info {
    flex-direction: row;
    justify-content: space-between;
    width: 100%;
    padding: 10px 12px;
  }
}

(function () {
  'use strict';

  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate');

  const SWATCH_COUNT = 5;
  let swatches = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  }

  function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generateHarmoniousPalette(baseHue) {
    const hue = baseHue !== undefined ? baseHue : randomInt(0, 359);
    const schemes = [
      [0, 30, 60, 90, 120],
      [0, 72, 144, 216, 288],
      [0, 180, 180, 0, 180],
      [0, 40, 80, 160, 200],
      [0, 15, 30, 45, 60]
    ];
    const scheme = schemes[randomInt(0, schemes.length - 1)];
    const sat = randomInt(55, 80);
    const lightBase = randomInt(40, 65);

    return scheme.map((offset, i) => {
      const h = (hue + offset) % 360;
      const l = Math.min(85, Math.max(25, lightBase + (i - 2) * 8));
      return hslToHex(h, sat, l);
    });
  }

  function createSwatchElement(color, index) {
    const swatch = document.createElement('div');
    swatch.className = 'swatch';
    swatch.dataset.index = index;

    const colorDiv = document.createElement('div');
    colorDiv.className = 'swatch-color';
    colorDiv.style.backgroundColor = color;
    colorDiv.setAttribute('aria-hidden', 'true');

    const info = document.createElement('div');
    info.className = 'swatch-info';

    const hexSpan = document.createElement('span');
    hexSpan.className = 'hex-code';
    hexSpan.textContent = color;

    const lockBtn = document.createElement('button');
    lockBtn.type = 'button';
    lockBtn.className = 'lock-btn';
    lockBtn.setAttribute('aria-pressed', 'false');
    lockBtn.setAttribute('aria-label', `Lock color ${color}`);
    lockBtn.dataset.index = index;

    const lockIcon = document.createElement('span');
    lockIcon.className = 'lock-icon';
    lockIcon.textContent = '\uD83D\uDD13';
    lockIcon.setAttribute('aria-hidden', 'true');

    const lockText = document.createElement('span');
    lockText.textContent = 'Lock';

    lockBtn.appendChild(lockIcon);
    lockBtn.appendChild(lockText);

    lockBtn.addEventListener('click', () => toggleLock(index, lockBtn, lockIcon, lockText));

    info.appendChild(hexSpan);
    info.appendChild(lockBtn);

    swatch.appendChild(colorDiv);
    swatch.appendChild(info);

    return { el: swatch, colorDiv, hexSpan, lockBtn, lockIcon, lockText, locked: false, color };
  }

  function toggleLock(index, lockBtn, lockIcon, lockText) {
    const swatch = swatches[index];
    swatch.locked = !swatch.locked;
    lockBtn.setAttribute('aria-pressed', String(swatch.locked));
    lockIcon.textContent = swatch.locked ? '\uD83D\uDD12' : '\uD83D\uDD13';
    lockText.textContent = swatch.locked ? 'Locked' : 'Lock';
    lockBtn.setAttribute('aria-label', `${swatch.locked ? 'Unlock' : 'Lock'} color ${swatch.color}`);
  }

  function updateSwatch(index, color) {
    const swatch = swatches[index];
    swatch.color = color;
    swatch.colorDiv.style.backgroundColor = color;
    swatch.hexSpan.textContent = color;
    if (!swatch.locked) {
      swatch.lockBtn.setAttribute('aria-label', `Lock color ${color}`);
    }
  }

  function renderPalette(colors) {
    paletteEl.innerHTML = '';
    swatches = [];
    colors.forEach((color, i) => {
      const swatch = createSwatchElement(color, i);
      swatches.push(swatch);
      paletteEl.appendChild(swatch.el);
    });
  }

  function generate() {
    const unlockedIndices = [];
    swatches.forEach((s, i) => {
      if (!s.locked) unlockedIndices.push(i);
    });

    if (unlockedIndices.length === 0) {
      return;
    }

    let baseHue;
    const lockedSwatch = swatches.find((s) => s.locked);
    if (lockedSwatch) {
      const hex = lockedSwatch.color.replace('#', '');
      const r = parseInt(hex.substring(0, 2), 16) / 255;
      const g = parseInt(hex.substring(2, 4), 16) / 255;
      const b = parseInt(hex.substring(4, 6), 16) / 255;
      const max = Math.max(r, g, b);
      const min = Math.min(r, g, b);
      const l = (max + min) / 2;
      let h = 0;
      if (max !== min) {
        const d = max - min;
        if (max === r) h = ((g - b) / d + (g < b ? 6 : 0)) / 6;
        else if (max === g) h = ((b - r) / d + 2) / 6;
        else h = ((r - g) / d + 4) / 6;
      }
      baseHue = Math.round(h * 360);
    }

    const newColors = generateHarmoniousPalette(baseHue);

    unlockedIndices.forEach((idx, i) => {
      updateSwatch(idx, newColors[i % newColors.length]);
    });
  }

  function init() {
    const colors = generateHarmoniousPalette();
    renderPalette(colors);
    generateBtn.addEventListener('click', generate);
  }

  init();
})();
